using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Find all errors
var errors = build.FindChildrenRecursive<Error>();
Console.WriteLine($"=== TOTAL ERRORS: {errors.Count} ===\n");

foreach (var error in errors)
{
    var project = GetParentProject(error);
    Console.WriteLine($"Project: {project}");
    Console.WriteLine($"Code: {error.Code}");
    Console.WriteLine($"File: {error.File}:{error.LineNumber}");
    Console.WriteLine($"Message: {error.Text}");
    Console.WriteLine("---");
}

// Find all warnings
var warnings = build.FindChildrenRecursive<Warning>();
Console.WriteLine($"\n=== TOTAL WARNINGS: {warnings.Count} ===\n");
foreach (var w in warnings)
{
    var project = GetParentProject(w);
    Console.WriteLine($"[{w.Code}] {project}: {w.Text}");
}

// Project results
Console.WriteLine("\n=== PROJECT BUILD RESULTS ===\n");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (!p.Succeeded)
        Console.WriteLine($"FAILED: {p.Name} [{p.TargetFramework}]");
}

static string GetParentProject(BaseNode node)
{
    var current = node.Parent;
    while (current != null)
    {
        if (current is Project p) return p.Name;
        current = current.Parent;
    }
    return "unknown";
}
EOF
