cat > /tmp/binlog-reader/Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Show project dependency graph
Console.WriteLine("=== PROJECT STRUCTURE ===\n");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"Project: {p.Name} (TFW: {p.TargetFramework})");
    // Find ProjectReference items
    var items = p.FindChildrenRecursive<Item>();
    foreach (var item in items)
    {
        if (item.Name == "ProjectReference")
            Console.WriteLine($"  -> References: {item.Text}");
    }
    // Find PackageReference items
    foreach (var item in items)
    {
        if (item.Name == "PackageReference")
            Console.WriteLine($"  [pkg] {item.Text}");
    }
}

// Check for restore issues
Console.WriteLine("\n=== PACKAGE RESTORE INFO ===\n");
var messages = build.FindChildrenRecursive<Message>();
foreach (var m in messages)
{
    if (m.Text != null && (m.Text.Contains("NU1101") || m.Text.Contains("PackageReference") || m.Text.Contains("Newtonsoft")))
        Console.WriteLine(m.Text);
}
EOF
